import { Component, OnInit } from '@angular/core';
import { Observable } from 'rxjs';
import { HistoryService } from '../../../../core/services/history.service';
import { AuthService } from '../../../../core/services/auth.service';
import { NotificationService } from '../../../../core/services/notification.service';
import { QuantityResponse } from '../../../../core/models/measurement.models';

@Component({
  selector: 'app-history-list',
  templateUrl: './history-list.component.html'
})
export class HistoryListComponent implements OnInit {

  // Async pipe in the template subscribes/unsubscribes automatically
  history$: Observable<QuantityResponse[]>;
  isLoggedIn = false;

  constructor(
    private historyService: HistoryService,
    private authService: AuthService,
    private notifService: NotificationService
  ) {
    this.history$ = this.historyService.history$;
  }

  ngOnInit(): void {
    this.isLoggedIn = this.authService.isLoggedIn;
  }

  refresh(): void {
    if (this.isLoggedIn) {
      this.historyService.loadFromServer().subscribe();
    } else {
      this.historyService.loadSession();
    }
  }

  clearAll(): void {
    if (this.isLoggedIn) {
      this.historyService.clearOnServer().subscribe({
        next: () => this.notifService.show('History cleared.', 'success'),
        error: () => this.notifService.show('Could not clear history.', 'error')
      });
    } else {
      this.historyService.clearSession();
    }
  }

  // Helper methods used in the template
  getDetail(item: QuantityResponse): string {
    const o1 = item.operand1, o2 = item.operand2;
    if (item.operation === 'Compare') return `${o1?.value} ${o1?.unit} vs ${o2?.value} ${o2?.unit}`;
    if (item.operation === 'Convert') return `${o1?.value} ${o1?.unit}`;
    return `${o1?.value} ${o1?.unit} · ${o2?.value} ${o2?.unit}`;
  }

  getResult(item: QuantityResponse): string {
    if (item.operation === 'Compare') return item.boolResult === true ? 'Equal' : 'Not Equal';
    if (item.operation === 'Convert') {
      const v = item.result?.value;
      return v != null ? `${(+v.toFixed(4))} ${item.result?.unit}` : '—';
    }
    const rv = item.scalarResult != null ? item.scalarResult : item.result?.value;
    return rv != null ? `${(+(rv as number).toFixed(4))} ${item.result?.unit ?? ''}` : '—';
  }

  getCategory(item: QuantityResponse): string {
    return item.operand1?.category || item.result?.category || '';
  }

  formatTime(timestamp?: string): string {
    if (!timestamp) return '';
    return new Date(timestamp).toLocaleTimeString();
  }
}
<div class="history-section">
  <div class="history-header">
    <div class="section-label" style="margin-bottom:0">Recent History</div>
    <div>
      <button style="margin-right:8px;background:var(--primary);color:white;border:none;border-radius:6px;padding:6px 12px;cursor:pointer;font-size:13px;font-weight:600"
              (click)="refresh()">
        Refresh
      </button>
      <button class="btn-clear" (click)="clearAll()">Clear All</button>
    </div>
  </div>

  <!-- async pipe auto-subscribes to history$ Observable -->
  <div class="history-list">
    <ng-container *ngIf="history$ | async as items">

      <!-- No history yet -->
      <div *ngIf="items.length === 0 && isLoggedIn"
           style="color:var(--muted);font-size:14px;text-align:center;padding:20px">
        No records yet.
      </div>

      <!-- Guest: show login prompt -->
      <div *ngIf="items.length === 0 && !isLoggedIn"
           style="color:var(--muted);font-size:14px;text-align:center;padding:30px 20px">
        <div style="font-size:28px;margin-bottom:10px">🔒</div>
        <div style="font-weight:600;margin-bottom:6px;color:var(--text)">Login to view history</div>
        <div style="margin-bottom:14px">Your calculation history is saved when you're logged in.</div>
        <a routerLink="/auth/login"
           style="background:var(--primary);color:#fff;border:none;border-radius:8px;padding:8px 20px;cursor:pointer;font-size:13px;font-weight:600;text-decoration:none;display:inline-block">
          Login / Sign Up
        </a>
      </div>

      <!-- History items -->
      <div class="history-item" *ngFor="let item of items">
        <span class="history-op">{{ item.operation }}</span>
        <div style="flex:1;margin:0 14px">
          <div class="history-detail">{{ getDetail(item) }}</div>
          <div class="history-time">{{ getCategory(item) }} · {{ formatTime(item.timestamp) }}</div>
        </div>
        <span class="history-result">{{ getResult(item) }}</span>
      </div>

    </ng-container>
  </div>
</div>
